{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ExpoPro - Exhibition & Event Solutions</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --primary: #1a1a2e;
            --accent: #e94560;
            --light: #f8f9fa;
            --gray: #6c757d;
            --border: #dee2e6;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            color: var(--primary);
            line-height: 1.6;
            background: #fff;
        }

        /* Cover */
        .cover {
            height: 100vh;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            color: white;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            padding: 40px;
            position: relative;
            overflow: hidden;
        }

        .cover::before {
            content: '';
            position: absolute;
            width: 600px;
            height: 600px;
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: 50%;
            top: -200px;
            right: -200px;
        }

        .cover::after {
            content: '';
            position: absolute;
            width: 400px;
            height: 400px;
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: 50%;
            bottom: -100px;
            left: -100px;
        }

        .logo {
            font-size: 48px;
            font-weight: 700;
            letter-spacing: 8px;
            margin-bottom: 20px;
        }

        .tagline {
            font-size: 18px;
            font-weight: 300;
            opacity: 0.8;
            letter-spacing: 4px;
            margin-bottom: 60px;
        }

        .cover-products {
            display: flex;
            gap: 40px;
            margin-top: 40px;
        }

        .cover-item {
            background: rgba(255,255,255,0.05);
            border: 1px solid rgba(255,255,255,0.1);
            padding: 30px 40px;
            border-radius: 8px;
            font-size: 14px;
            letter-spacing: 2px;
        }

        /* Section */
        .section {
            padding: 80px 60px;
            min-height: 100vh;
        }

        .section-title {
            font-size: 36px;
            font-weight: 600;
            margin-bottom: 10px;
        }

        .section-subtitle {
            font-size: 14px;
            color: var(--gray);
            letter-spacing: 3px;
            text-transform: uppercase;
            margin-bottom: 60px;
        }

        /* Category Index */
        .category-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 30px;
        }

        .category-card {
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 40px 30px;
            text-align: center;
            transition: all 0.3s ease;
            cursor: pointer;
        }

        .category-card:hover {
            border-color: var(--accent);
            transform: translateY(-5px);
            box-shadow: 0 20px 40px rgba(0,0,0,0.08);
        }

        .category-icon {
            width: 60px;
            height: 60px;
            background: var(--light);
            border-radius: 50%;
            margin: 0 auto 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 24px;
        }

        .category-name {
            font-size: 16px;
            font-weight: 500;
            margin-bottom: 8px;
        }

        .category-count {
            font-size: 12px;
            color: var(--gray);
        }

        /* Product Grid */
        .product-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 40px;
        }

        .product-card {
            border: 1px solid var(--border);
            border-radius: 12px;
            overflow: hidden;
            transition: all 0.3s ease;
        }

        .product-card:hover {
            box-shadow: 0 20px 60px rgba(0,0,0,0.1);
        }

        .product-image {
            height: 280px;
            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 80px;
            color: #adb5bd;
            position: relative;
        }

        .product-badge {
            position: absolute;
            top: 20px;
            left: 20px;
            background: var(--accent);
            color: white;
            padding: 6px 14px;
            border-radius: 20px;
            font-size: 11px;
            font-weight: 500;
            letter-spacing: 1px;
        }

        .product-info {
            padding: 30px;
        }

        .product-name {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 15px;
        }

        .product-specs {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 12px;
            font-size: 13px;
        }

        .spec-item {
            display: flex;
            justify-content: space-between;
            padding: 8px 0;
            border-bottom: 1px solid var(--border);
        }

        .spec-label {
            color: var(--gray);
        }

        .spec-value {
            font-weight: 500;
        }

        /* Comparison Table */
        .comparison-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 40px;
        }

        .comparison-table th,
        .comparison-table td {
            padding: 18px 20px;
            text-align: left;
            border-bottom: 1px solid var(--border);
        }

        .comparison-table th {
            background: var(--light);
            font-weight: 600;
            font-size: 13px;
            letter-spacing: 1px;
            text-transform: uppercase;
            color: var(--gray);
        }

        .comparison-table tr:hover {
            background: #fafbfc;
        }

        .comparison-table .highlight {
            background: rgba(233, 69, 96, 0.05);
        }

        /* Feature Highlight */
        .feature-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 60px;
            margin-top: 60px;
        }

        .feature-item {
            display: flex;
            gap: 30px;
        }

        .feature-number {
            font-size: 48px;
            font-weight: 700;
            color: var(--accent);
            opacity: 0.3;
            line-height: 1;
        }

        .feature-content h4 {
            font-size: 20px;
            margin-bottom: 12px;
        }

        .feature-content p {
            color: var(--gray);
            font-size: 14px;
        }

        /* Materials Section */
        .material-cards {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 40px;
            margin-top: 60px;
        }

        .material-card {
            border-radius: 16px;
            padding: 50px;
            color: white;
        }

        .material-card.steel {
            background: linear-gradient(135deg, #434343 0%, #2b2b2b 100%);
        }

        .material-card.aluminum {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        }

        .material-card h3 {
            font-size: 28px;
            margin-bottom: 20px;
        }

        .material-pros {
            list-style: none;
            margin-top: 30px;
        }

        .material-pros li {
            padding: 10px 0;
            display: flex;
            align-items: center;
            gap: 12px;
            opacity: 0.9;
        }

        .material-pros li::before {
            content: '✓';
            width: 20px;
            height: 20px;
            background: rgba(255,255,255,0.2);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
        }

        /* Footer */
        .footer {
            background: var(--primary);
            color: white;
            padding: 80px 60px;
            text-align: center;
        }

        .footer-logo {
            font-size: 32px;
            font-weight: 700;
            letter-spacing: 6px;
            margin-bottom: 30px;
        }

        .footer-contact {
            display: flex;
            justify-content: center;
            gap: 60px;
            margin-top: 40px;
        }

        .contact-item {
            opacity: 0.7;
            font-size: 14px;
        }

        .contact-item strong {
            display: block;
            opacity: 1;
            margin-bottom: 8px;
        }

        /* Navigation Dots */
        .nav-dots {
            position: fixed;
            right: 30px;
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .nav-dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            background: #ddd;
            cursor: pointer;
            transition: all 0.3s;
        }

        .nav-dot.active {
            background: var(--accent);
            transform: scale(1.3);
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .category-grid,
            .product-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .feature-grid,
            .material-cards {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 768px) {
            .section {
                padding: 60px 30px;
            }

            .category-grid,
            .product-grid {
                grid-template-columns: 1fr;
            }

            .cover-products {
                flex-direction: column;
                gap: 20px;
            }

            .comparison-table {
                font-size: 13px;
            }
        }
    </style>
</head>
<body>
    <!-- Navigation Dots -->
    <div class="nav-dots">
        <div class="nav-dot active" data-section="cover"></div>
        <div class="nav-dot" data-section="contents"></div>
        <div class="nav-dot" data-section="steel-tents"></div>
        <div class="nav-dot" data-section="aluminum-tents"></div>
        <div class="nav-dot" data-section="comparison"></div>
        <div class="nav-dot" data-section="accessories"></div>
    </div>

    <!-- Cover -->
    <section class="cover" id="cover">
        <div class="logo">EXPOPRO</div>
        <div class="tagline">PREMIUM EXHIBITION SOLUTIONS</div>
        <p style="opacity: 0.6; max-width: 500px; margin-bottom: 40px;">
            Professional exhibition tents, event furniture & display solutions for global trade shows and events
        </p>
        <div class="cover-products">
            <div class="cover-item">TENTS</div>
            <div class="cover-item">FURNITURE</div>
            <div class="cover-item">DISPLAYS</div>
            <div class="cover-item">ACCESSORIES</div>
        </div>
    </section>

    <!-- Contents -->
    <section class="section" id="contents">
        <h2 class="section-title">Product Catalog</h2>
        <p class="section-subtitle">2024 Collection</p>

        <div class="category-grid">
            <div class="category-card">
                <div class="category-icon">⛺</div>
                <div class="category-name">Steel Tents</div>
                <div class="category-count">8 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">🏕️</div>
                <div class="category-name">Aluminum Tents</div>
                <div class="category-count">12 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">🪑</div>
                <div class="category-name">Director Chairs</div>
                <div class="category-count">6 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">🖼️</div>
                <div class="category-name">Rollup Displays</div>
                <div class="category-count">10 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">📦</div>
                <div class="category-name">Pop-up Walls</div>
                <div class="category-count">8 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">🏖️</div>
                <div class="category-name">Beach Umbrellas</div>
                <div class="category-count">5 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">💡</div>
                <div class="category-name">Light Boxes</div>
                <div class="category-count">6 Models</div>
            </div>
            <div class="category-card">
                <div class="category-icon">🔗</div>
                <div class="category-name">Display Frames</div>
                <div class="category-count">4 Models</div>
            </div>
        </div>
    </section>

    <!-- Steel Tents -->
    <section class="section" id="steel-tents">
        <h2 class="section-title">Steel Exhibition Tents</h2>
        <p class="section-subtitle">Heavy-duty • Cost-effective • Durable</p>

        <div class="feature-grid">
            <div class="feature-item">
                <div class="feature-number">01</div>
                <div class="feature-content">
                    <h4>Galvanized Steel Frame</h4>
                    <p>Anti-rust powder coating, suitable for long-term outdoor use</p>
                </div>
            </div>
            <div class="feature-item">
                <div class="feature-number">02</div>
                <div class="feature-content">
                    <h4>Easy Setup</h4>
                    <p>Tool-free assembly in 5-10 minutes</p>
                </div>
            </div>
            <div class="feature-item">
                <div class="feature-number">03</div>
                <div class="feature-content">
                    <h4>Multiple Sizes</h4>
                    <p>From 2x2m to 6x12m custom configurations</p>
                </div>
            </div>
            <div class="feature-item">
                <div class="feature-number">04</div>
                <div class="feature-content">
                    <h4>Weather Resistant</h4>
                    <p>Waterproof, UV protection, wind resistant up to 40km/h</p>
                </div>
            </div>
        </div>

        <div class="product-grid" style="margin-top: 60px;">
            <div class="product-card">
                <div class="product-image">
                    ⛺
                    <span class="product-badge">BESTSELLER</span>
                </div>
                <div class="product-info">
                    <div class="product-name">Steel Tent 3x3m</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">3x3m</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">28 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Frame</span>
                            <span class="spec-value">Steel 32mm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Fabric</span>
                            <span class="spec-value">450g PVC</span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="product-card">
                <div class="product-image">⛺</div>
                <div class="product-info">
                    <div class="product-name">Steel Tent 4x4m</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">4x4m</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">42 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Frame</span>
                            <span class="spec-value">Steel 38mm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Fabric</span>
                            <span class="spec-value">450g PVC</span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="product-card">
                <div class="product-image">⛺</div>
                <div class="product-info">
                    <div class="product-name">Steel Tent 6x6m</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">6x6m</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">85 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Frame</span>
                            <span class="spec-value">Steel 42mm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Fabric</span>
                            <span class="spec-value">650g PVC</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Aluminum Tents -->
    <section class="section" id="aluminum-tents" style="background: var(--light);">
        <h2 class="section-title">Aluminum Exhibition Tents</h2>
        <p class="section-subtitle">Lightweight • Premium • Portable</p>

        <div class="material-cards">
            <div class="material-card aluminum">
                <h3>Aluminum Series</h3>
                <p>Premium extruded aluminum alloy frame with anodized finish</p>
                <ul class="material-pros">
                    <li>Ultra lightweight - 40% lighter than steel</li>
                    <li>Anti-corrosion - No rust</li>
                    <li>Aircraft-grade material</li>
                    <li>Quick fold system</li>
                    <li>Elegant appearance</li>
                </ul>
            </div>
            <div class="material-card steel">
                <h3>Steel Series</h3>
                <p>Heavy-duty galvanized steel frame with powder coating</p>
                <ul class="material-pros">
                    <li>Cost-effective solution</li>
                    <li>Superior stability</li>
                    <li>High load capacity</li>
                    <li>Long service life</li>
                    <li>Easy repair & replace</li>
                </ul>
            </div>
        </div>

        <div class="product-grid" style="margin-top: 60px;">
            <div class="product-card">
                <div class="product-image">🏕️</div>
                <div class="product-info">
                    <div class="product-name">Aluminum Tent 2x2m</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">2x2m</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">8.5 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Frame</span>
                            <span class="spec-value">Aluminum 30mm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Fabric</span>
                            <span class="spec-value">300g Polyester</span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="product-card">
                <div class="product-image">🏕️</div>
                <div class="product-info">
                    <div class="product-name">Aluminum Tent 3x3m</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">3x3m</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">15 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Frame</span>
                            <span class="spec-value">Aluminum 40mm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Fabric</span>
                            <span class="spec-value">300g Polyester</span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="product-card">
                <div class="product-image">🏕️</div>
                <div class="product-info">
                    <div class="product-name">Aluminum Tent 3x4.5m</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">3x4.5m</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">22 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Frame</span>
                            <span class="spec-value">Aluminum 40mm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Fabric</span>
                            <span class="spec-value">300g Polyester</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </section>

    <!-- Comparison -->
    <section class="section" id="comparison">
        <h2 class="section-title">Steel vs Aluminum</h2>
        <p class="section-subtitle">Technical Comparison</p>

        <table class="comparison-table">
            <thead>
                <tr>
                    <th>Specification</th>
                    <th>Steel 3x3m</th>
                    <th>Aluminum 3x3m</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Frame Material</td>
                    <td>Galvanized Steel</td>
                    <td>Aluminum Alloy 6063</td>
                </tr>
                <tr>
                    <td>Frame Thickness</td>
                    <td>1.2mm</td>
                    <td>1.5mm</td>
                </tr>
                <tr>
                    <td>Total Weight</td>
                    <td>28 kg</td>
                    <td>15 kg</td>
                </tr>
                <tr class="highlight">
                    <td>Weight Difference</td>
                    <td>-</td>
                    <td><strong>-46%</strong></td>
                </tr>
                <tr>
                    <td>Setup Time</td>
                    <td>10-15 min</td>
                    <td>5-8 min</td>
                </tr>
                <tr>
                    <td>Wind Resistance</td>
                    <td>40 km/h</td>
                    <td>30 km/h</td>
                </tr>
                <tr>
                    <td>Price Range</td>
                    <td>$180-220</td>
                    <td>$280-350</td>
                </tr>
                <tr class="highlight">
                    <td>Best For</td>
                    <td>Long-term events, heavy use</td>
                    <td>Frequent travel, quick events</td>
                </tr>
            </tbody>
        </table>
    </section>

    <!-- Accessories -->
    <section class="section" id="accessories" style="background: var(--light);">
        <h2 class="section-title">Accessories & More</h2>
        <p class="section-subtitle">Complete Event Solutions</p>

        <div class="product-grid">
            <div class="product-card">
                <div class="product-image">🪑</div>
                <div class="product-info">
                    <div class="product-name">Director Chair</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Material</span>
                            <span class="spec-value">Steel/Aluminum</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">4-6 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Load</span>
                            <span class="spec-value">150 kg</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Colors</span>
                            <span class="spec-value">Multiple</span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="product-card">
                <div class="product-image">🖼️</div>
                <div class="product-info">
                    <div class="product-name">Rollup / Pop-up Display</div>
                    <div class="product-specs">
                        <div class="spec-item">
                            <span class="spec-label">Size</span>
                            <span class="spec-value">80x200cm</span>
                        </div>
                        <div class="spec-item">
                            <span class="spec-label">Weight</span>
                            <span class="spec-value">3-4 kg</span>
                        </div>
